<script lang="ts">
	import { AlertTriangle, CheckCircle2 } from '@lucide/svelte';
	import BmsCompactCellResistanceTable from './BmsCompactCellResistanceTable.svelte';
	import BmsCompactCellVoltageTable from './BmsCompactCellVoltageTable.svelte';
	import type { InitialBaselineStageFiveActions, InitialBaselineStageFiveModel } from './initial-baseline-stage-form';

	let { model, actions }: { model: InitialBaselineStageFiveModel; actions: InitialBaselineStageFiveActions } = $props();
	let editable = $derived(!model.readOnly && !model.busy);
	let floatEditor = $state(false);
	let floatMinA = $state('');
	let floatMaxA = $state('');
	let floatReason = $state('');
	let vocEditor = $state(false);
	let vocDeadbandA = $state('');
	let vocReason = $state('');

	async function submitFloatPolicy() {
		const minA = Number(floatMinA);
		const maxA = Number(floatMaxA);
		if (!editable || !floatReason.trim() || !Number.isFinite(minA) || !Number.isFinite(maxA)
				|| minA < 0 || maxA < minA) return;
		try {
			await actions.changeRecoveryFloatRange(minA, maxA, floatReason);
			floatEditor = false;
			floatReason = '';
		} catch {
			// The parent renders the authoritative backend error and refreshed event.
		}
	}

	async function submitVocPolicy() {
		const deadbandA = Number(vocDeadbandA);
		if (!editable || !vocReason.trim() || !Number.isFinite(deadbandA) || deadbandA < 0) return;
		try {
			await actions.changeVocDeadband(deadbandA, vocReason);
			vocEditor = false;
			vocReason = '';
		} catch {
			// Keep the editor values available so the operator can correct/retry.
		}
	}
</script>

<section class="recovery-workflow" data-mode={model.mode}>
	<label class="confirm"><input type="checkbox" checked={model.recoveryMcbClosed} disabled={!editable || model.recoveryStarted} onchange={(event) => actions.setRecoveryMcbClosed(event.currentTarget.checked)} /><span><strong>Confirm charger DC MCB is closed</strong><small>Reconnect the charger before starting the recovery charge.</small></span></label>
	{#if model.recoveryMcbClosed}
		<div class="charge-targets"><div><span>Vboost target</span><strong>{model.boostVoltage.toFixed(1)} V</strong><small>{model.boostVoltagePerCell.toFixed(2)} V/cell × {model.cellCount} cells</small></div><div><span>Vfloat target</span><strong>{model.floatVoltage.toFixed(1)} V</strong><small>{model.floatVoltagePerCell.toFixed(2)} V/cell × {model.cellCount} cells</small></div><div><span>Current limit</span><strong>{model.currentLimit.toFixed(1)} A</strong><small>Configured for this event</small></div></div>
		<label class="confirm"><input type="checkbox" checked={model.recoverySettingsVerified} disabled={!editable || model.recoveryStarted} onchange={(event) => actions.setRecoverySettingsVerified(event.currentTarget.checked)} /><span><strong>Verify recovery charge settings</strong><small>Targets match the verified configuration for this event.</small></span></label>
	{/if}
	{#if model.recoveryMcbClosed && model.recoverySettingsVerified && !model.recoveryStarted}<button class="secondary start" disabled={!editable} onclick={actions.startRecovery}>Start recovery charge</button>{/if}
	{#if model.recoveryStarted && !model.recoveryFloatStarted}<div class:ready={model.recoveryChargeComplete} class="charge-status"><div class="status-head"><div><span>Recovery boost charge</span><strong>{model.recoveryChargeComplete ? 'Vboost target reached' : 'Charging to Vboost'}</strong></div><b>{model.recoveryBoostVoltage?.toFixed(1) ?? '—'} V / {model.recoveryBoostEffectiveTargetVoltage.toFixed(1)} V</b></div><div class="progress"><i style={`width:${model.recoveryProgress}%`}></i></div>{#if model.mode === 'real'}<div class="live-charge-metrics"><div><span>Processed string voltage</span><strong>{model.recoveryBoostVoltage?.toFixed(1) ?? '—'} V</strong></div><div><span>Nominal target (25 °C)</span><strong>{model.boostVoltage.toFixed(1)} V</strong><small>{model.boostVoltagePerCell.toFixed(3)} V/cell × {model.cellCount}</small></div><div><span>Effective target</span><strong>{model.recoveryBoostEffectiveTargetVoltage.toFixed(1)} V</strong><small>{model.recoveryBoostProcessedTemperatureC === null ? 'Waiting for cell temperature' : `Temperature-compensated at ${model.recoveryBoostProcessedTemperatureC.toFixed(1)} °C`}</small></div></div><p class="live-snapshot-note">The bar is the processed string voltage against the backend temperature-compensated target. The backend alone confirms completion.</p>{/if}{#if !model.recoveryChargeComplete}<div class="waiting"><i></i>{model.mode === 'demo' ? 'Recovery charging · demo time accelerated' : 'Waiting for the authoritative recovery process'}</div>{/if}</div>{/if}
	{#if model.recoveryChargeComplete && !model.recoveryFloatStarted}<div class="auto-transition"><CheckCircle2 size={16} />Vboost reached — waiting for the Float process.</div>{/if}
	{#if model.recoveryFloatStarted && !model.recoveryFloatReached}<div class="charge-status"><div class="status-head"><div><span>Float charge</span><strong>Settling to Vfloat</strong></div><b>{model.recoveryFloatVoltage?.toFixed(1) ?? '—'} V / {model.recoveryFloatEffectiveTargetVoltage.toFixed(1)} V</b></div><div class="progress float-progress"><i style={`width:${model.recoveryFloatProgress}%`}></i></div>{#if model.mode === 'real'}<div class="live-charge-metrics"><div><span>Processed string voltage</span><strong>{model.recoveryFloatVoltage?.toFixed(1) ?? '—'} V</strong></div><div><span>Nominal target (25 °C)</span><strong>{model.floatVoltage.toFixed(1)} V</strong><small>{model.floatVoltagePerCell.toFixed(3)} V/cell × {model.cellCount}</small></div><div><span>Effective target</span><strong>{model.recoveryFloatEffectiveTargetVoltage.toFixed(1)} V</strong><small>{model.recoveryFloatProcessedTemperatureC === null ? 'Waiting for cell temperature' : `Temperature-compensated at ${model.recoveryFloatProcessedTemperatureC.toFixed(1)} °C`}</small></div></div><p class="live-snapshot-note">The bar is the processed string voltage against the backend temperature-compensated target. The backend alone confirms completion.</p>{/if}<div class="waiting"><i></i>Charger output is reducing to the configured Vfloat target</div></div>{/if}
	{#if model.recoveryFloatReached}<div class:ready={model.recoveryFloatComplete} class="float-stable"><div class="status-head"><div><span>Float stable mode</span><strong>{model.recoveryFloatComplete ? 'Stable window complete' : 'Holding within Float voltage range'}</strong></div><b>{model.recoveryFloatStableProgress}%</b></div><div class="progress float-progress"><i style={`width:${model.recoveryFloatStableProgress}%`}></i></div><div class="float-metrics"><div><span>Current voltage</span><strong>{model.recoveryFloatVoltage?.toFixed(1) ?? '—'} V</strong><small>{model.recoveryFloatEffectiveTargetVoltage.toFixed(1)} ± {model.recoveryFloatVoltageToleranceV.toFixed(1)} V</small></div><div><span>Current charge</span><strong>{model.recoveryFloatCurrentA?.toFixed(2) ?? '—'} A</strong><small>{model.recoveryFloatCurrentMinA.toFixed(2)}–{model.recoveryFloatCurrentMaxA.toFixed(2)} A</small></div><div><span>Stable duration</span><strong>{model.recoveryFloatElapsedSeconds} / {model.recoveryFloatStableSeconds} sec</strong><small>{model.mode === 'demo' ? 'Demo uses a real-time 60-second window' : 'Persisted backend process status'}</small></div></div>{#if !model.recoveryFloatComplete && (model.recoveryFloatCurrentA === null || Math.abs(model.recoveryFloatCurrentA) < model.recoveryFloatCurrentMinA || Math.abs(model.recoveryFloatCurrentA) > model.recoveryFloatCurrentMaxA)}<div class="float-warning"><AlertTriangle size={17} /><div><strong>Float stable window is waiting for current in range</strong><span>{#if model.recoveryFloatCurrentA === null}The process has not returned a current measurement.{:else}Current magnitude {Math.abs(model.recoveryFloatCurrentA).toFixed(2)} A is outside the configured {model.recoveryFloatCurrentMinA.toFixed(2)}–{model.recoveryFloatCurrentMaxA.toFixed(2)} A range.{/if}</span><small>The backend keeps the stable duration at zero until a valid snapshot satisfies the active policy.</small></div></div>{/if}{#if model.canChangeRecoveryFloatRange}<button class="secondary" onclick={() => { floatEditor = !floatEditor; floatMinA = model.recoveryFloatCurrentMinA.toString(); floatMaxA = model.recoveryFloatCurrentMaxA.toString(); }}>Change Float-current range</button>{/if}{#if floatEditor && model.canChangeRecoveryFloatRange}<section class="policy-editor"><strong>Change active Float-current range</strong><span>The stable timer will restart from zero.</span><div><input type="number" min="0" step="0.01" bind:value={floatMinA} aria-label="Recovery Float minimum current" /><input type="number" min="0" step="0.01" bind:value={floatMaxA} aria-label="Recovery Float maximum current" /></div><textarea maxlength="512" placeholder="Required reason" bind:value={floatReason}></textarea><button class="secondary" disabled={!editable || !floatReason.trim() || !Number.isFinite(Number(floatMinA)) || !Number.isFinite(Number(floatMaxA)) || Number(floatMinA) < 0 || Number(floatMaxA) < Number(floatMinA)} onclick={submitFloatPolicy}>Apply range and restart timer</button></section>{/if}</div>{/if}
	{#if model.recoveryFloatComplete}<label class="confirm"><input type="checkbox" checked={model.recoveryFloatConfirmed} disabled={!editable || model.recoveryFloatConfirmed} onchange={(event) => actions.setRecoveryFloatConfirmed(event.currentTarget.checked)} /><span><strong>Confirm Float condition is stable</strong><small>Review the stable-window voltage and current before recording baseline measurements.</small></span></label>{/if}

	{#if model.recoveryFloatConfirmed}
		<BmsCompactCellResistanceTable cells={model.resistanceCells} expectedCount={model.cellCount} description={`${model.resistanceCells.length} of ${model.cellCount} cells recorded after the Float stable window.`} />
		<label class="confirm"><input type="checkbox" checked={model.resistanceConfirmed} disabled={!editable || model.resistanceConfirmed} onchange={(event) => actions.setResistanceConfirmed(event.currentTarget.checked)} /><span><strong>Confirm every cell resistance is recorded</strong><small>Average resistance: {model.averageResistanceUohm} µΩ. Review the IR outlier warning before continuing.</small></span></label>
	{/if}

	{#if model.recoveryFloatConfirmed && model.resistanceConfirmed}
		<section class="baseline-measurements"><header><div><span>Baseline measurements — no load</span><strong>Record these values before connecting the load.</strong></div><small>Required</small></header>
			<div class="measurement-grid"><label><span>Float current (mA)</span><input type="number" min="0" value={model.floatCurrent} disabled={!editable || model.mode === 'real'} oninput={(event) => actions.setFloatCurrent(event.currentTarget.value)} /><input type="checkbox" checked={model.floatCurrentConfirmed} disabled={!editable || !model.floatCurrent.trim() || model.floatCurrent === '—'} onchange={(event) => actions.setFloatCurrentConfirmed(event.currentTarget.checked)} /></label>{#if model.floatCurrentConfirmed}<label><span>Midpoint voltage (V)</span><input type="number" step="0.1" value={model.midpointVoltage} disabled={!editable || model.mode === 'real'} oninput={(event) => actions.setMidpointVoltage(event.currentTarget.value)} /><input type="checkbox" checked={model.midpointConfirmed} disabled={!editable || !model.midpointVoltage.trim() || model.midpointVoltage === '—'} onchange={(event) => actions.setMidpointConfirmed(event.currentTarget.checked)} /></label>{/if}{#if model.midpointConfirmed}<label><span>AC ripple — no load (V)</span><input type="number" step="0.1" value={model.rippleNoLoad} disabled={!editable || model.rippleNoLoadConfirmed} onfocus={() => actions.setRippleNoLoadFocused(true)} onblur={() => actions.setRippleNoLoadFocused(false)} oninput={(event) => actions.setRippleNoLoad(event.currentTarget.value)} /><input type="checkbox" checked={model.rippleNoLoadConfirmed} disabled={!editable || !model.rippleNoLoad.trim()} onchange={(event) => actions.setRippleNoLoadConfirmed(event.currentTarget.checked)} /></label>{/if}</div>
		</section>
	{/if}
	{#if model.floatCurrentConfirmed && model.midpointConfirmed && model.rippleNoLoadConfirmed}<label class="confirm"><input type="checkbox" checked={model.loadConnected} disabled={!editable || model.loadConnected} onchange={(event) => actions.setLoadConnected(event.currentTarget.checked)} /><span><strong>Confirm load is connected</strong><small>Connect the operating load before taking the loaded ripple reading.</small></span></label>{/if}
	{#if model.loadConnected}<div class="loaded-ripple"><span>AC ripple — with load (V)</span><input type="number" min="0" step="0.1" value={model.rippleWithLoad} disabled={!editable || model.rippleWithLoadConfirmed} onfocus={() => actions.setRippleWithLoadFocused(true)} onblur={() => actions.setRippleWithLoadFocused(false)} oninput={(event) => actions.setRippleWithLoad(event.currentTarget.value)} /><label><input type="checkbox" checked={model.rippleWithLoadConfirmed} disabled={!editable || model.rippleWithLoadConfirmed || !model.rippleWithLoad.trim()} onchange={(event) => actions.setRippleWithLoadConfirmed(event.currentTarget.checked)} />Confirm measured</label></div>{/if}
	{#if model.rippleWithLoadConfirmed}<label class="confirm"><input type="checkbox" checked={model.chargerMcbOpen} disabled={!editable || model.chargerMcbOpen} onchange={(event) => actions.setChargerMcbOpen(event.currentTarget.checked)} /><span><strong>Confirm charger DC MCB is open</strong><small>Isolate the charger before the persisted Voc snapshot is captured.</small></span></label>{/if}
	{#if model.chargerMcbOpen && !model.vocSampleId}<div class="waiting voc-wait"><i></i>{model.vocLoading ? 'Loading persisted Voc snapshot…' : `Waiting for fresh current ≤ ${model.vocCurrentDeadbandA.toFixed(3)} A and complete persisted cell voltages…`}</div>{/if}
	{#if model.canChangeVocDeadband}<button class="secondary" onclick={() => { vocEditor = !vocEditor; vocDeadbandA = model.vocCurrentDeadbandA.toString(); }}>Change Voc current deadband</button>{/if}
	{#if vocEditor && model.canChangeVocDeadband}<section class="policy-editor"><strong>Change active Voc current deadband</strong><span>Only a new BMS snapshot after this change can be accepted.</span><input type="number" min="0" step="0.001" bind:value={vocDeadbandA} aria-label="Voc current deadband" /><textarea maxlength="512" placeholder="Required reason" bind:value={vocReason}></textarea><button class="secondary" disabled={!editable || !vocReason.trim() || !Number.isFinite(Number(vocDeadbandA)) || Number(vocDeadbandA) < 0} onclick={submitVocPolicy}>Apply Voc deadband</button></section>{/if}
	{#if model.vocError}<div class="warning">{model.vocError}. Live telemetry is not used as a fallback.</div>{/if}
	{#if model.vocSampleId}
		<section class="voc-snapshot"><div class="data-heading"><div><h4>Persisted Voc baseline</h4><p>{model.vocCapturedAt ?? 'Measurement time not recorded'} · sample #{model.vocSampleId}</p></div><span>FINAL</span></div><div class="voc-metrics"><article><span>String voltage</span><strong>{model.vocStringVoltage?.toFixed(3) ?? '—'} V</strong><small>Persisted FINAL_SNAPSHOT</small></article><article><span>Current</span><strong>{model.vocCurrentA?.toFixed(3) ?? '—'} A</strong><small>Persisted domain current · |I| ≤ {model.vocCurrentDeadbandA.toFixed(3)} A</small></article><article><span>Cell voltages</span><strong>{model.vocCells.filter((cell) => cell.voltage !== null).length}/{model.cellCount}</strong><small>Exact persisted sample</small></article></div><BmsCompactCellVoltageTable cells={model.vocCells} expectedCount={model.cellCount} title="Cell Data · Open-circuit Voltage" ariaLabel="Persisted Initial Baseline Voc cell voltages" emptyMessage="No persisted Voc cell voltage is available." />
			<label class="confirm"><input type="checkbox" checked={model.vocConfirmed} disabled={!editable || model.vocConfirmed} onchange={(event) => actions.setVocConfirmed(event.currentTarget.checked)} /><span><strong>Confirm persisted Voc baseline data</strong><small>Confirm the exact string voltage and per-cell voltage snapshot shown above.</small></span></label>
		</section>
	{/if}
</section>

<style>
	.recovery-workflow{display:grid;gap:14px}.confirm{display:flex;align-items:flex-start;gap:10px;padding:13px 14px;border-radius:11px;color:#52647e;background:#f6f8fb;cursor:pointer}.confirm input,.measurement-grid input[type=checkbox],.loaded-ripple input[type=checkbox]{width:17px;height:17px;flex:none;margin:1px 0 0;accent-color:#1749ad}.confirm span{display:grid;gap:3px}.confirm strong{color:#40516d;font-size:13px;font-weight:500}.confirm small{color:#7b899d;font-size:11px;line-height:1.4}.charge-targets{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.charge-targets div{display:grid;gap:5px;padding:13px 14px;border-radius:11px;background:#f6f8fb}.charge-targets span,.charge-status span{color:#718096;font-size:11px}.charge-targets strong{color:#30415d;font-size:16px;font-weight:500}.charge-targets small{color:#7b899d;font-size:10px}.secondary{justify-self:start;min-height:37px;padding:0 13px;border:1px solid #d7dfeb;border-radius:8px;color:#40516f;background:#fff;font:inherit;cursor:pointer}.secondary:disabled{opacity:.55;cursor:not-allowed}.charge-status,.float-stable{display:grid;gap:10px;padding:16px;border-radius:11px;background:#f0f5fd}.charge-status.ready,.float-stable.ready{background:#edf9f1}.status-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.status-head div{display:grid;gap:3px}.status-head strong{color:#294f91;font-size:14px;font-weight:500}.status-head b{color:#315b9f;font-size:13px;font-weight:500}.progress{height:6px;overflow:hidden;border-radius:99px;background:#dce7f8}.progress i{display:block;height:100%;border-radius:inherit;background:#3267c4}.float-progress{background:#dceee3}.float-progress i{background:#4f8a6a}.live-charge-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.live-charge-metrics>div{display:grid;gap:4px;padding:10px;border-radius:8px;background:rgba(255,255,255,.72)}.live-charge-metrics span,.live-charge-metrics small{color:#718096;font-size:10px}.live-charge-metrics strong{color:#30415d;font-size:14px;font-weight:500}.live-snapshot-note{margin:0;color:#657a99;font-size:11px}.waiting{display:flex;align-items:center;gap:7px;color:#5e7598;font-size:12px}.waiting i{width:8px;height:8px;border-radius:50%;background:#4778ce;animation:pulse 1.1s ease-in-out infinite}@keyframes pulse{50%{opacity:.3;transform:scale(.7)}}.auto-transition{display:flex;align-items:center;gap:7px;color:#347350;font-size:12px}.float-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.float-metrics>div{display:grid;gap:4px;padding:10px;border-radius:8px;background:rgba(255,255,255,.72)}.float-metrics span,.float-metrics small{color:#718096;font-size:10px}.float-metrics strong{color:#30415d;font-size:14px;font-weight:500}.baseline-measurements{overflow:hidden;border-radius:11px;background:#f6f8fb}.baseline-measurements header{display:flex;align-items:start;justify-content:space-between;gap:12px;padding:13px 14px;border-bottom:1px solid #e6edf5}.baseline-measurements header div{display:grid;gap:3px}.baseline-measurements header span{color:#718096;font-size:11px}.baseline-measurements header strong{color:#40516d;font-size:13px;font-weight:500}.baseline-measurements header small{padding:4px 7px;border-radius:99px;color:#396b50;background:#e6f5eb;font-size:10px}.measurement-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;padding:13px 14px}.measurement-grid label{display:grid;grid-template-columns:1fr 17px;gap:5px 8px;align-items:center;color:#5f6f86;font-size:11px}.measurement-grid label>span{grid-column:1/-1}.measurement-grid input[type=number],.loaded-ripple>input{width:100%;min-height:37px;padding:0 9px;border:0;border-radius:7px;color:#34465f;background:#fff;box-shadow:inset 0 0 0 1px #e4eaf2;font:inherit;font-size:13px}.loaded-ripple{display:grid;grid-template-columns:1fr 115px auto;align-items:end;gap:10px;padding:13px 14px;border-radius:11px;background:#f6f8fb;color:#5f6f86;font-size:11px}.loaded-ripple label{display:flex;align-items:center;gap:6px;min-height:37px}.voc-wait{padding:13px 14px;border-radius:9px;background:#f0f5fd}.warning{padding:10px 14px;border-radius:8px;color:#795a22;background:#fff9e9;font-size:12px}.voc-snapshot{display:grid;gap:11px;padding:14px;border:1px solid #dce6f3;border-radius:11px;background:#f7f9fc}.data-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.data-heading div{display:grid;gap:4px}.data-heading h4{margin:0;color:#30415d;font-size:14px;font-weight:500}.data-heading p{margin:0;color:#718096;font-size:11px}.data-heading>span{padding:4px 7px;border-radius:999px;color:#28734b;background:#e5f5eb;font-size:10px;font-weight:600}.voc-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.voc-metrics article{display:grid;gap:4px;padding:11px;border-radius:8px;background:#fff}.voc-metrics span,.voc-metrics small{color:#718096;font-size:10px}.voc-metrics strong{color:#30415d;font-size:14px;font-weight:500}@media(max-width:800px){.measurement-grid{grid-template-columns:1fr}.loaded-ripple{grid-template-columns:1fr 120px}.voc-metrics{grid-template-columns:1fr}}@media(max-width:650px){.charge-targets,.live-charge-metrics,.float-metrics,.voc-metrics{grid-template-columns:1fr}.status-head,.data-heading{align-items:flex-start;flex-direction:column}.loaded-ripple{grid-template-columns:1fr}}
	.policy-editor{display:grid;gap:9px;padding:12px;border:1px solid #d7dfeb;border-radius:9px;background:#fff}.policy-editor>span{font-size:11px;color:#7b899d}.policy-editor>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.policy-editor input,.policy-editor textarea{min-height:37px;padding:8px;border:1px solid #d7dfeb;border-radius:7px;font:inherit}.policy-editor textarea{min-height:62px;resize:vertical}.float-warning{display:flex;align-items:flex-start;gap:9px;padding:11px 12px;border-radius:8px;color:#87541d;background:#fff8e8}.float-warning :global(svg){flex:none;margin-top:1px}.float-warning div{display:grid;gap:3px}.float-warning strong{font-size:12px;font-weight:600}.float-warning span,.float-warning small{font-size:11px;line-height:1.4}.float-warning small{color:#806b50}
</style>
